EXEMPLARS: Dict[str, List[Exemplar]] = {'gsm8k': GSM8K, 'math_algebra': MATH_ALGEBRA, 'arc_challenge': ARC_CHALLENGE, 'strategyqa': STRATEGYQA, 'boardgameqa': BOARDGAMEQA, 'gpqa_diamond': GPQA_DIAMOND}

def format_exemplar(ex: Exemplar, delimiter: str=DELIMITER) -> str:
    return f'Q: {ex.question}\nA: {ex.rationale} {delimiter} {ex.answer}.'

def build_prompt(question: str, exemplars: List[Exemplar], delimiter: str=DELIMITER) -> str:
    """k-shot prompt: exemplars separated by blank lines, then the target question with an open 'A:'."""
    blocks = [format_exemplar(e, delimiter) for e in exemplars]
    blocks.append(f'Q: {question}\nA:')
    return '\n\n'.join(blocks)

def completion_text(rationale: str, answer: str, delimiter: str=DELIMITER) -> str:
    """Training target for IB fine-tuning (continuation after 'A:')."""
    return f' {rationale.strip()} {delimiter} {answer}.'
